def ueberfuehren(apps, schema_editor):
    """Frühere Zustände in den Ablauf ohne Abnahme überführen; Ergebnisse, Prüfungen, Meldungen
    und Revisionen bleiben unverändert. Jede Umstellung steht im Verlauf des Auftrags."""
